#!/bin/bash
set -e
#
# Qingke Panel - remote manager / installer
# Generated by build.sh, DO NOT edit the checksum table manually.
#
# Usage:
#   curl -fsSL https://<CDN>/qingliang-install.sh | sudo bash
#   bash qingliang-install.sh install|uninstall|info|restart
#

CDN_BASE="https://sh.851109.xyz/qlweb"
PKG_PATH=""
PKG_VERSION="20260819162301"
PANEL_PORT="${PANEL_PORT:-}"
PANEL_DIR="${PANEL_DIR:-/opt/qingliang}"

PKG_PATH="${PKG_PATH%/}"
PKG_URL="$CDN_BASE${PKG_PATH:+/$PKG_PATH}"

declare -A PKG_HASHES
PKG_HASHES["panel.py"]="5737cad6a6f441d485e8e5c57cfe62c8508b18b8aa1037a59bfd6163e2443595"
PKG_HASHES["web/index.html"]="2b79dea96088747a065f2761c881bb3e7ce0bcad76c94f5d8be47d6b34e86ea3"
PKG_HASHES["web/style.css"]="a9305bf18fdf55e49237b1bc47ed1d2483fa718bf86b491e67c4c70d2758c52d"
PKG_HASHES["web/app.js"]="bbc3e409f1c6701709960e17abc55eb970e5796f805d91bf300d8a4ee1447896"


read_line() {
    if [ -t 0 ]; then
        read -r "$1"
    elif { exec 3<>/dev/tty; } 2>/dev/null; then
        read -r "$1" <&3
        exec 3>&- 2>/dev/null || true
    else
        read -r "$1"
    fi
}

root_check() {
    if [ "$(id -u)" != "0" ]; then
        echo "ERROR: must run as root."
        echo "Try: curl -fsSL $CDN_BASE/qingliang-install.sh | sudo bash"
        exit 1
    fi
}

get_ip() {
    curl -s -4 ifconfig.me 2>/dev/null || curl -s -4 ip.sb 2>/dev/null || echo "YOUR_SERVER_IP"
}

get_port() {
    if [ -f /etc/systemd/system/qingliang.service ]; then
        grep -oP 'Environment=PANEL_PORT=\K[0-9]+' /etc/systemd/system/qingliang.service | head -1
    else
        echo "${PANEL_PORT:-8888}"
    fi
}

ask_port() {
    local input=""
    if [ -n "$PANEL_PORT" ]; then
        return
    fi
    local d=8888
    if [ -t 0 ]; then
        echo "请输入面板端口（回车使用默认 $d）："
        read -r input
    elif { exec 3<>/dev/tty; } 2>/dev/null; then
        echo "请输入面板端口（回车使用默认 $d）：" >&3
        read -r input <&3
        exec 3>&- 2>/dev/null || true
    fi
    if [ -z "$input" ]; then
        PANEL_PORT="$d"
        return
    fi
    case "$input" in
        *[!0-9]*)
            echo "端口无效，使用默认 $d"
            PANEL_PORT="$d" ;;
        *)
            if [ "$input" -ge 1 ] 2>/dev/null && [ "$input" -le 65535 ]; then
                PANEL_PORT="$input"
            else
                echo "端口超出范围 1-65535，使用默认 $d"
                PANEL_PORT="$d"
            fi ;;
    esac
}

get_credentials() {
    if [ -f "$PANEL_DIR/panel.conf" ]; then
        python3 -c "
import json
c = json.load(open('$PANEL_DIR/panel.conf'))
print(c.get('username', 'qingke'))
print(c.get('password', 'qingke123'))
" 2>/dev/null || echo -e "qingke\nqingke123"
    else
        echo -e "qingke\nqingke123"
    fi
}

cmd_install() {
    root_check
    echo "== Qingke Panel install =="
    echo "  CDN:      $CDN_BASE"
    echo "  Version:  $PKG_VERSION"
    ask_port
    echo "  Panel:    $PANEL_DIR   port $PANEL_PORT"

    export DEBIAN_FRONTEND=noninteractive

    if ! command -v curl >/dev/null 2>&1; then
        echo "[deps] installing curl ..."
        apt-get update -y >/dev/null 2>&1 || true
        apt-get install -y curl >/dev/null 2>&1
    fi

    STAGE=$(mktemp -d)
    trap 'rm -rf "$STAGE"' EXIT

    fetch() {
        local rel="$1"
        local out="$STAGE/$rel"
        local expected="${PKG_HASHES[$rel]}"
        mkdir -p "$(dirname "$out")"
        echo "[fetch] $PKG_URL/$rel"
        curl -fsSL --retry 3 -o "$out" "$PKG_URL/$rel?v=$PKG_VERSION" || {
            echo "ERROR: failed to download $PKG_URL/$rel"
            exit 1
        }
        if [ -n "$expected" ]; then
            local actual
            actual=$(sha256sum "$out" | awk '{print $1}')
            if [ "$actual" != "$expected" ]; then
                echo "ERROR: checksum mismatch for $rel"
                echo "  expected: $expected"
                echo "  actual:   $actual"
                exit 1
            fi
        fi
    }

    echo "[download] pulling package files from $PKG_URL"
    fetch panel.py
    fetch web/index.html
    fetch web/style.css
    fetch web/app.js

    echo "[deps] installing nginx, python3, certbot ..."
    apt-get update -y
    apt-get install -y nginx python3 certbot python3-certbot-nginx

    if ! nginx -v 2>&1 | grep -q "nginx"; then
        echo "ERROR: nginx install failed"
        exit 1
    fi

    echo "[deploy] installing to $PANEL_DIR"
    mkdir -p "$PANEL_DIR/web"
    cp "$STAGE/panel.py" "$PANEL_DIR/panel.py"
    cp -r "$STAGE/web/." "$PANEL_DIR/web/"
    chmod +x "$PANEL_DIR/panel.py"

    cat > /etc/systemd/system/qingliang.service <<EOF
[Unit]
Description=Qingke Panel
After=network.target nginx.service

[Service]
Type=simple
WorkingDirectory=$PANEL_DIR
ExecStart=/usr/bin/python3 $PANEL_DIR/panel.py
Restart=always
RestartSec=3
Environment=PANEL_PORT=$PANEL_PORT
Environment=PANEL_HOST=0.0.0.0

[Install]
WantedBy=multi-user.target
EOF

    systemctl daemon-reload
    systemctl enable qingliang
    systemctl restart qingliang

    cat > /etc/nginx/sites-available/default <<'EOF'
# Qingke Panel: reject requests for unbound hosts (no fallback page)
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    return 444;
}
EOF

    systemctl enable nginx
    systemctl start nginx

    IP=$(get_ip)
    PORT=$(get_port)
    CRED=$(get_credentials)
    USER=$(echo "$CRED" | sed -n 1p)
    PASS=$(echo "$CRED" | sed -n 2p)

    echo
    echo "=========================================================="
    echo " Install finished!"
    echo
    echo " Panel URL:   http://$IP:$PORT"
    echo " Username:    $USER"
    echo " Password:    $PASS"
    echo
    echo " Login and change username/password in Settings."
    echo "=========================================================="
}

cmd_uninstall() {
    root_check
    echo "== Qingke Panel uninstall =="
    echo "This will remove panel files and systemd service."
    if [ -d "$PANEL_DIR" ] || [ -f /etc/systemd/system/qingliang.service ]; then
        echo -n "Continue? [y/N] "
        local ans
        read_line ans
        case "$ans" in
            y|Y)
                systemctl stop qingliang 2>/dev/null || true
                systemctl disable qingliang 2>/dev/null || true
                rm -f /etc/systemd/system/qingliang.service
                systemctl daemon-reload
                rm -rf "$PANEL_DIR"
                echo "Panel uninstalled."
                ;;
            *)
                echo "Cancelled."
                ;;
        esac
    else
        echo "Panel is not installed."
    fi
}

cmd_info() {
    if [ ! -f "$PANEL_DIR/panel.conf" ] && [ ! -f /etc/systemd/system/qingliang.service ]; then
        echo "Panel is not installed yet."
        echo "Run install first: bash qingliang-install.sh install"
        return
    fi
    IP=$(get_ip)
    PORT=$(get_port)
    CRED=$(get_credentials)
    USER=$(echo "$CRED" | sed -n 1p)
    PASS=$(echo "$CRED" | sed -n 2p)
    echo "=========================================================="
    echo " Qingke Panel info"
    echo
    echo " Panel URL:   http://$IP:$PORT"
    echo " Username:    $USER"
    echo " Password:    $PASS"
    echo " Panel dir:   $PANEL_DIR"
    echo " Version:     $PKG_VERSION"
    echo "=========================================================="
}

cmd_restart() {
    root_check
    if [ -f /etc/systemd/system/qingliang.service ]; then
        systemctl restart qingliang
        echo "Panel restarted."
    else
        echo "Panel is not installed."
    fi
}

menu() {
    echo
    echo "============================================"
    echo "   轻壳面板 Qingke Panel Manager"
    echo "============================================"
    echo "  1) 全新安装"
    echo "  2) 完全卸载"
    echo "  3) 查看面板信息"
    echo "  4) 重启面板"
    echo "  0) 退出"
    echo "============================================"
}

case "${1:-}" in
    install)   cmd_install ;;
    uninstall) cmd_uninstall ;;
    info)      cmd_info ;;
    restart)   cmd_restart ;;
    "")
        while true; do
            menu
            echo -n "请选择 [0-4]: "
            choice=""
            read_line choice
            case "$choice" in
                1) cmd_install ;;
                2) cmd_uninstall ;;
                3) cmd_info ;;
                4) cmd_restart ;;
                0) echo "再见"; exit 0 ;;
                *) echo "无效选择，请重试。" ;;
            esac
        done
        ;;
    *)
        echo "Unknown command: $1"
        echo "Usage: bash qingliang-install.sh install|uninstall|info|restart"
        exit 1
        ;;
esac
